window.CHAPTERS={"war":{"slug":"war","from":1941,"to":1945,"kicker":"Глава 2 · 1941–1945","title":"Всё для фронта","subtitle":"Как жили и работали Николаевск и район в годы Великой Отечественной войны","intro":["Николаевск-на-Амуре был далеко от линий фронта, но война пришла и сюда. Уже в 1941 году хлеб и сахар стали выдавать по карточкам, выпускницы курсов медицинских сестёр почти всем составом ушли на фронт, а в районе работали оборонные кружки и спортивные секции.","Главной работой города были река и море. Порт и пароходство обслуживали Сахалин и Охотское побережье, судоремонтный завод вышел из стройки в цеха, землечерпалки углубляли Амурский фарватер — чтобы корабли, построенные в Комсомольске-на-Амуре, смогли выйти на большую воду. Через Николаевск шли и грузы по ленд-лизу.","Работали все. В воспоминаниях жительницы села Красное Валентины Ивановны Шлудовой — «всё лежало на плечах женщин»: они рыбачили, сажали картошку, а школьники вязали рукавицы, собирали посылки на фронт и нянчили малышей. А летом 1945 года суда николаевского пароходства перевозили войска и грузы для освобождения южной части Сахалина."],"key":["С 1941 года — карточная система на хлеб, сахар и кондитерские изделия.","1942: подводный канал на Амуре готов — по нему проведён крейсер «Калинин»; пароходство перевозит 163 тыс. т грузов и получает Знамя Государственного Комитета Обороны.","1943: в строй вступает судоремонтный завод; 1944: на нём строят первую металлическую баржу (500 т).","Николаевцы собирают деньги в Фонд обороны, тёплые вещи для воинов и помощь освобождённым районам.","Лето 1945: суда пароходства везут на Сахалин более 80 тыс. т грузов и 4 тыс. военнослужащих.","К 1946 году валовая продукция промышленности области почти вдвое выше, чем в 1940-м."],"timeline":[{"year":1941,"id":179,"title":"Карточки на хлеб и сахар"},{"year":1941,"id":180,"title":"Нефтепровод Оха — Комсомольск через мыс Лазарева"},{"year":1941,"id":187,"title":"Первый выпуск медсестёр уходит на фронт"},{"year":1941,"id":194,"title":"Школа в селе Красное: воспоминания очевидца"},{"year":1941,"id":198,"title":"Театр переходит на военный репертуар"},{"year":1941,"id":190,"title":"Взлётная полоса между реками Камора и Личи"},{"year":1941,"id":186,"title":"Училище № 12 готовит кадры для судозавода"},{"year":1942,"id":201,"title":"Фарватер для кораблей Комсомольска: крейсер «Калинин»"},{"year":1942,"id":206,"title":"Порт готовится принимать суда на Камчатку"},{"year":1942,"id":207,"title":"Пароходство: 163 тысячи тонн и Знамя ГКО"},{"year":1942,"id":205,"title":"«Тёплая одежда для воинов»"},{"year":1942,"id":204,"title":"Рекордная картошка колхоза «Красный Май»"},{"year":1942,"id":202,"title":"Токари судоверфи и орден Нины Кузнецовой"},{"year":1942,"id":208,"title":"Вступил в строй порт Маго"},{"year":1943,"id":210,"title":"Фонд обороны: 11,5 миллиона рублей"},{"year":1943,"id":211,"title":"Ленд-лиз в порту"},{"year":1943,"id":212,"title":"Судоремонтный завод в строю"},{"year":1943,"id":217,"title":"Морской техникум"},{"year":1943,"id":220,"title":"Дорога по улице Советской"},{"year":1943,"id":209,"title":"Хлебокомбинат"},{"year":1943,"id":221,"title":"Помощь освобождённым районам"},{"year":1944,"id":232,"title":"Первая металлическая баржа — 500 тонн"},{"year":1944,"id":235,"title":"Ремесленное училище переезжает на завод"},{"year":1944,"id":238,"title":"Как школьникам помогали одеждой и обувью"},{"year":1944,"id":234,"title":"Создан краеведческий музей"},{"year":1944,"id":237,"title":"Артель инвалидов войны «Рассвет»"},{"year":1945,"id":241,"title":"Суда пароходства идут на Сахалин"},{"year":1945,"id":242,"title":"Итоги: промышленность выросла почти вдвое"},{"year":1945,"id":244,"title":"Забота о детях и цена победы"}],"compare":[{"title":"Промышленность области выросла почти вдвое","note":"Валовая продукция промышленности, тыс. рублей (без золотодобычи)","a":{"label":"1940","value":26016},"b":{"label":"1946","value":50271},"id":242}],"stack":{"title":"Что николаевцы отдали фронту","note":"За первые два года войны, млн рублей","parts":[{"label":"Наличными в Фонд обороны","value":5.5},{"label":"Облигациями госзайма","value":6.0},{"label":"На самолёты и танки","value":2.5}],"id":210},"people":[{"name":"Валентина Ивановна Шлудова","role":"Жительница села Красное, очевидец","text":"Её воспоминания о школе и детях в годы войны вошли в хронологию: школьники вязали рукавицы и носки, отправляли посылки на фронт и по очереди нянчили малышей в избе-читальне.","id":194},{"name":"Нина Петровна Кузнецова","role":"Работница судоверфи","text":"Среди 33 работников предприятия, награждённых за досрочное выполнение задания, — удостоена ордена «Знак Почёта». Судоверфь точила детали для каравана земснарядов.","id":202},{"name":"Николай Киров и Иван Мухин","role":"Бригадиры грузчиков порта","text":"В навигацию 1942 года выполняли нормы выработки в отдельные дни на 200–250 % и 150–200 %.","id":207},{"name":"Нина Теплоухова, Анна Грозина, Анна Плотникова","role":"Звеньевые колхоза «Красный Май»","text":"С шести гектаров получили картофеля 161,5; 138 и 149,6 центнера с гектара — о них написано в справке 1942 года об итогах работы.","id":204},{"name":"Пётр Васильевич Рукавишников","role":"Первый директор судоремонтного завода","text":"Завод стал самым крупным предприятием города; станочный парк частично оборудовали за счёт поставок по ленд-лизу из США.","id":212},{"name":"М. Бородин","role":"Первый директор судоверфи","text":"С 1941 года верфь строила деревянные лодки «Астраханка» для рыбаков Нижнего Амура; заложен первый малый сейнер.","id":184}],"glossary":[["Карточная система","Распределение продуктов по нормам: хлеб, сахар и другие товары выдавали не свободно, а по специальным карточкам."],["Ленд-лиз","Программа поставок США своим союзникам в годы войны: оборудование, продовольствие, вооружение. Часть станков николаевского судоремонтного завода была получена по ленд-лизу."],["Фонд обороны","Добровольные взносы граждан на нужды армии: деньги, облигации, тёплые вещи."],["ГТО","«Готов к труду и обороне» — комплекс норм по физической подготовке. Значкисты — те, кто сдал нормы и получил значок."],["Кунгас","Несамоходное плоскодонное судно для перевозки грузов и рыбы по реке."],["Плашкоут","Несамоходное плоскодонное судно (баржа), которое использовали для погрузки и разгрузки на рейде."],["Сейнер","Рыболовное судно, которое ловит рыбу неводом."],["Слип","Наклонная площадка на берегу, по которой суда спускают на воду и поднимают для ремонта."],["Земснаряд (землечерпалка)","Судно, которое углубляет дно реки и бухт, чтобы могли пройти большие корабли."],["Ряжевый причал","Причал из деревянных срубов — ряжей, заполненных камнем или грунтом."]],"quiz":[{"q":"Что ввели с началом войны для выдачи хлеба и сахара?","options":["Талоны на обед в столовых","Карточную систему","Продовольственные рынки","Трудодни"],"a":1,"why":"С началом войны отпуск хлеба, сахара и кондитерских изделий пошёл по карточкам.","id":179},{"q":"Сколько судов было в транспортном флоте Николаевского пароходства в 1942 году?","options":["3","9","25","60"],"a":1,"why":"Девять судов перевезли за год 163 тыс. т грузов; годовой план выполнили 22 октября.","id":207},{"q":"Какой крейсер провели по углублённому фарватеру Амура в 1942 году?","options":["«Аврора»","«Варяг»","«Калинин»","«Киров»"],"a":2,"why":"Крейсер «Калинин», спущенный на воду в Комсомольске-на-Амуре, прибыл на дежурство во Владивосток.","id":201},{"q":"Кто присматривал за малышами в селе Красное, где не было ни детсада, ни яслей?","options":["Бабушки-пенсионерки","Школьники постарше","Сотрудники колхоза","Воспитатели гарнизона"],"a":1,"why":"Ребят сводили в избу-читальню, где за малышами присматривали дети постарше: варили каши, кормили, играли.","id":194},{"q":"Сколько тёплых вещей для воинов собрали организации Николаевска к 1 октября 1942 года?","options":["Около 300","Около 3 тысяч","Свыше 29 тысяч","Более 200 тысяч"],"a":2,"why":"Свыше 29 тысяч: шубы и полушубки, валенки, телогрейки и брюки, тёплое бельё, портянки.","id":205},{"q":"Какое судно впервые построили на судоремонтном заводе в 1944 году?","options":["Крейсер","Деревянный сейнер","Металлическую баржу на 500 т","Ледокол"],"a":2,"why":"Первая металлическая баржа грузоподъёмностью 500 тонн.","id":232},{"q":"Куда летом 1945 года суда пароходства перевозили воинские грузы?","options":["На Камчатку","На северо-запад Сахалина","В Японию","На Курилы"],"a":1,"why":"На северо-западное побережье Сахалина, в частности в Москальво — более 80 тыс. т грузов и 4 тыс. военнослужащих.","id":241},{"q":"Сколько николаевцы внесли в Фонд обороны наличными за первые два года войны?","options":["550 тысяч рублей","5,5 млн рублей","55 млн рублей","5 тысяч рублей"],"a":1,"why":"5,5 млн наличными и ещё 6 млн облигациями госзайма; сверх этого — 2,5 млн на самолёты и танки.","id":210}],"tasks":["Прочитайте воспоминание В. И. Шлудовой. Какие «взрослые» дела делали дети в селе Красное? Что вы думаете об этом?","Найдите на карте Амур, Амурский лиман и Сахалин. Почему углублённый фарватер был так важен для кораблей, построенных в Комсомольске-на-Амуре?","Составьте список предприятий, появившихся в 1941–1945 годах. Какие из них были нужны для фронта, а какие — для мирной жизни?","Сравните числа в блоке «В цифрах». Какие говорят о нагрузке на порт, какие — о помощи фронту, какие — о заботе о детях?","Почему заметка «Тёплая одежда для воинов» опубликована осенью? Что нужно было сделать до зимы?"],"sources":["Текст записей — хронология автора проекта.","В записях упомянуты газета «Красный маяк» (1941, 1942) и воспоминания очевидцев.","Источники по каждой записи уточняются; список проверки ведётся в файле data/vychitka_war.csv."],"mapLinks":[{"title":"Дорога по улице Советской (1943)","text":"В 1943 году при участии горожан начали строить дорогу по улице Советской — основную дорогу, связывающую город с гидропортом и военным аэродромом, с судостроительным заводом № 3 и с селом Красное.","streets":["Советская улица"]}]},"postwar":{"slug":"postwar","from":1946,"to":1953,"kicker":"Глава 3 · 1946–1953","title":"От карточек к автобусам","subtitle":"Как город и район возвращались к мирной жизни: новые заводы, небо над Севером и первые городские автобусы","intro":["После войны Николаевск жил по мирным меркам. В 1947 году отменили карточки на продовольствие и промышленные товары. Открылись ателье мод и краеведческий музей, развернули больницу, а в городской поликлинике появилась рентгеновская аппаратура. Первым делом для города строили электростанции: в 1946-м — городскую, а в посёлке Маго электричество в дома впервые дали в конце года.","Опорой города оставались порт и судостроение. В 1946 году на судостроительном заводе заработал сухой док, в 1947-м завод начал строить морские буксиры, а в 1953-м судоверфь перешла на металлические суда: плотники осваивали профессию клепальщиков. За два года на завод приехало около 200 специалистов с высшим образованием и более 800 выпускников ПТУ и ФЗО со всей страны.","Появилось и небо. В 1948 году организовали авиаотряд из трёх самолётов ПО-2 и двух амфибий: зимой они взлетали со льда залива. В 1951-м с новыми самолётами Ан-2 авиация начала обслуживать Тугуро-Чумиканский, Аяно-Майский и Охотский районы. А в городе открылось автобусное движение: проезд стоил 25 копеек, кинотеатр «Родина» показывал широкоформатные фильмы, а улицы Советская, Горького, Сибирская, Приамурская, Красноармейская и Орлова осветили."],"key":["1947: отменены карточки на продовольствие и промышленные товары.","1946: на судостроительном заводе введён сухой док; первым в него ввели пароход «Ола».","1948: организован авиаотряд — 3 самолёта ПО-2 и 2 амфибии Ш-2; в 1951-м Ан-2 открывают воздушные трассы на Север.","1950: первый автобусный маршрут — Мельзавод — Хлебокомбинат; проезд 25 копеек.","1951: открыт кинотеатр «Родина», освещены основные улицы, работает детская музыкальная школа.","1953: судоверфь переходит на металл; на завод приезжают около 200 специалистов и 800+ выпускников профессиональных училищ."],"timeline":[{"year":1946,"id":245,"title":"Строится городская электростанция"},{"year":1946,"id":248,"title":"Пароход «Ола» — первый корабль в сухом доке"},{"year":1946,"id":250,"title":"Краеведческий музей открыт для посещений"},{"year":1946,"id":252,"title":"Маго получает электричество"},{"year":1947,"id":253,"title":"Регулярные рейсы на Южный Сахалин"},{"year":1947,"id":254,"title":"Школа юнг для рыбопромыслового флота"},{"year":1947,"id":255,"title":"Завод строит морские буксиры"},{"year":1947,"id":256,"title":"Отмена карточек"},{"year":1948,"id":257,"title":"Больница: диспансеры, рентген, зубопротезный кабинет"},{"year":1948,"id":258,"title":"Подготовительное отделение для народов Севера"},{"year":1948,"id":260,"title":"Родился авиаотряд: 3 ПО-2 и 2 амфибии"},{"year":1948,"id":262,"title":"Лесотарный комбинат в Маго"},{"year":1949,"id":264,"title":"Мореходная школа"},{"year":1949,"id":267,"title":"Механический завод на Первом Номере"},{"year":1949,"id":270,"title":"Колхозы: новые фермы и 647 тысяч центнеров рыбы"},{"year":1950,"id":278,"title":"Первый автобус: проезд — 25 копеек"},{"year":1950,"id":275,"title":"Пивоваренный завод"},{"year":1950,"id":277,"title":"Изостудия при клубе судоверфи"},{"year":1950,"id":280,"title":"Интернат в селе Красное для детей народов Нижнего Амура"},{"year":1950,"id":283,"title":"Город в 1950 году: чем жил и что производил"},{"year":1950,"id":287,"title":"Баночная фабрика в Маго: воспоминание Ю. Д. Зюкова"},{"year":1951,"id":292,"title":"144-й объединённый авиаотряд и Ан-2"},{"year":1951,"id":296,"title":"Пляж, карусель и свет на улицах"},{"year":1951,"id":299,"title":"Кинотеатр «Родина»"},{"year":1951,"id":300,"title":"Судоверфь: лесопильное хозяйство"},{"year":1951,"id":295,"title":"Детская школа искусств"},{"year":1952,"id":303,"title":"Новое здание школы № 1"},{"year":1952,"id":305,"title":"Музыкальная школа открывает первые классы"},{"year":1952,"id":306,"title":"Книги для библиотеки Маго"},{"year":1953,"id":308,"title":"Судоверфь переходит на металл"},{"year":1953,"id":312,"title":"Со всей страны — строить корабли"},{"year":1953,"id":316,"title":"Вступил в строй Лазаревский порт"},{"year":1953,"id":317,"title":"Дом пионеров получает своё здание"},{"year":1953,"id":307,"title":"Открыта городская библиотека"},{"year":1953,"id":314,"title":"Библиотека в селе Красное"}],"compare":[{"title":"Школа в селе Красное растёт","note":"Учеников в Красносельской школе","a":{"label":"1948","value":127},"b":{"label":"1949","value":160},"id":263}],"stack":{"title":"Первый авиаотряд Николаевска (1948)","note":"Самолёты в распоряжении отряда","unit":" шт.","parts":[{"label":"Самолёты ПО-2","value":3},{"label":"Амфибии Ш-2","value":2}],"id":260},"mapLinks":[{"title":"Улицы, которые осветили в 1951 году","text":"В 1951 году электрическое освещение получили улицы Советская, Горького, Сибирская, Приамурская, Красноармейская и Орлова. Найдите их на карте города.","streets":["Советская улица","улица Горького","Сибирская улица","Приамурская улица","Красноармейская улица","улица Орлова"]}],"people":[{"name":"Виктор Кравец","role":"Командир первого авиаотряда","text":"Вместе с демобилизованными лётчиками Богатырёвым, Мацневым, Бойко, Коробышевым, Илюхиным, Шанским, Шариковым и Шустенко начинал гражданскую авиацию Николаевска. Лётчики работали по 10–12 часов в сутки.","id":260},{"name":"Сергей Ерлыкин","role":"Первый руководитель 144-го объединённого авиаотряда","text":"Приехал в 1951 году из Сасовского лётного училища. Под его руководством самолёты Ан-2 открыли трассы на Нелькан, Аян, Чумикан и Курун-Урях.","id":292},{"name":"Юрий Данилович Зюков","role":"Жил в Маго, вспоминает в подростковом возрасте","text":"Мальчишкой в 7 классе летом подрабатывал на баночной фабрике: носил жестяные банки в коробках на баржу — их отправляли на рыбозаводы. Цеха, вспоминает он, были светлые и чистые, и росло много цветов.","id":287},{"name":"Е. М. Толстова","role":"Заведующая школьным интернатом в селе Красное","text":"В интернате жили и учились дети народов нижнего Амура из Чнырраха, Каменки и микрорайонов села Красное.","id":280},{"name":"Василий Георгиевич Шумилкин","role":"Первый библиотекарь села Красное","text":"Член ВЛКСМ с образованием 6 классов, прошедший обучение при детской библиотеке. Начинал с 2 423 книг в помещении площадью 20 кв. м.","id":314}],"glossary":[["Сухой док","Сооружение для ремонта судов: судно заводят внутрь, воду откачивают, и корпус остаётся на сухом дне."],["Амфибия","Самолёт, который может взлетать и садиться как на землю, так и на воду. Ш-2 — советская лёгкая амфибия."],["ПО-2","Лёгкий многоцелевой самолёт, на котором летали и в войну, и после неё."],["Ан-2","Многоцелевой самолёт, способный работать на небольших площадках, — именно он открыл воздушные трассы на Север."],["ФЗО","Школы фабрично-заводского обучения: в них готовили рабочих для заводов и строек."],["МТС","Машинно-тракторная станция: предприятие, которое давало колхозам технику и механизаторов."],["Изба-читальня","Сельская библиотека и центр просвещения: газеты, книги, лекции для жителей села."],["Книгоношество","Способ доставки книг: библиотекари носили и возили книги к читателям — на фермы, рыбацкие заездки."],["Народы Севера","Коренные малочисленные народы: на Нижнем Амуре живут нивхи, ульчи, негидальцы, эвены и эвенки."]],"quiz":[{"q":"Что отменили в 1947 году?","options":["Налог на рыболовство","Карточки на продовольствие и промтовары","Пропуск в порт","Школьную форму"],"a":1,"why":"Карточки, введённые в начале войны, отменили на продовольствие и на промышленные товары.","id":256},{"q":"Какое судно первым ввели в сухой док судостроительного завода?","options":["«Ерофей Хабаров»","«Ола»","«Калинин»","«Лена»"],"a":1,"why":"Грузопассажирский пароход «Ола». Земснаряд «Лена» промывал перемычку — он помог ввести пароход в док.","id":248},{"q":"Сколько стоил проезд в первом городском автобусе в 1950 году?","options":["5 копеек","25 копеек","1 рубль","3 рубля"],"a":1,"why":"25 копеек. Первый маршрут соединял Мельзавод и Хлебокомбинат.","id":278},{"q":"Сколько самолётов было в первом авиаотряде Николаевска (1948 год)?","options":["2","5","12","30"],"a":1,"why":"Пять: три самолёта ПО-2 и две амфибии Ш-2.","id":260},{"q":"Откуда зимой взлетали самолёты авиаотряда в 1948 году?","options":["С бетонной полосы аэропорта","Со льда залива","С палубы корабля","С поля колхоза"],"a":1,"why":"Зимой со льда залива, а летом — с сухопутного аэродрома воинской части.","id":260},{"q":"Какой кинотеатр открыли в 1951 году?","options":["«Октябрь»","«Родина»","«Заря»","«Космос»"],"a":1,"why":"Кинотеатр «Родина» с возможностью широкоэкранного показа фильмов.","id":299},{"q":"На какое судостроение перешла судоверфь в 1953 году?","options":["Пластиковое","Металлическое","Деревянное","Бетонное"],"a":1,"why":"На металлическое: рабочие-судоплотники осваивали профессию клепальщиков, а позже перешли к сварке.","id":308},{"q":"Кто стал первым руководителем 144-го объединённого авиаотряда?","options":["Виктор Кравец","Сергей Ерлыкин","Пётр Рукавишников","Семён Богатырёв"],"a":1,"why":"Сергей Ерлыкин, прибывший из Сасовского лётного училища. Виктор Кравец командовал предшественником — 257-м авиаотрядом.","id":292}],"tasks":["Найдите на карте улицы, которые осветили в 1951 году. Что их объединяет? Почему, как вы думаете, начали именно с них?","Сравните 1941 и 1953 годы. Что появилось для детей: школы, интернаты, кружки, музыкальная школа, Дом пионеров, школа искусств?","Первый автобусный маршрут соединил Мельзавод и Хлебокомбинат. Что это говорит о том, какие места были важны городу? Какие маршруты нужны сегодня?","Прочитайте воспоминание Ю. Д. Зюкова о баночной фабрике и сравните с воспоминанием В. И. Шлудовой из главы о войне. Что общего и чем отличается детство в эти годы?","Судоверфь перешла с дерева на металл. Какие профессии уходили, а какие появлялись? Что ещё в истории города менялось из-за новой технологии?"],"sources":["Текст записей — хронология автора проекта.","В записях есть воспоминания очевидцев (Ю. Д. Зюков, В. Г. Шумилкин и др.).","Источники по каждой записи уточняются; список проверки — data/vychitka_postwar.csv."]},"growth":{"slug":"growth","from":1954,"to":1964,"kicker":"Глава 4 · 1954–1964","title":"Из дерева — в камень и сталь","subtitle":"Каменные дома, объединённый судостроительный завод, вертолёты над Севером и первое судно «река — море»","intro":["В середине 1950-х Николаевск строился. В 1955 году в городе жили 38 702 человека, а вместе с пригородной зоной — более 50,5 тысячи. За пять лет построили 89 одно- и двухэтажных домов на 747 квартир, а в 1956 году на улице Школьной заселили первый каменный трёхэтажный дом. Открылись психоневрологическая, инфекционная и детская больницы, детская поликлиника и женская консультация; в 1957 году в городе заасфальтировали более 21,5 тысячи квадратных метров дорог и тротуаров.","Главным делом города оставалось судостроение. В 1954 году завод приобрёл радиоактивный изотоп для контроля сварных швов, в 1957-м в доке установили башенные краны. В 1960 году судоверфь и судоремонтный завод объединили в судостроительный завод; его первым директором стал Наум Львович Кунин, а завод и верфь соединила отсыпанная через мелководный заливчик «дорога дружбы». В 1962–1963 годах литейный цех перешёл с чугуна на сталь, а в 1964-м завод построил первый на Дальнем Востоке сухогрузный теплоход «река — море» — «Морской-1» грузоподъёмностью 2000 тонн. Он возил экспортную древесину в Японию.","Север становился ближе. В 1956 году в авиаотряде появился первый вертолёт Ми-1 — «Копеечка», в 1958-м — самолёты Ли-2, в 1960-м — вертолёты Ми-4. За 1960 год николаевские авиаторы перевезли 40 922 пассажира, а в 1963-м отряд стал объединённым: в него вошли аэропорты северных районов края. В 1959 году теплоход «Ерофей Хабаров» прошёл из Хабаровска за 40 часов вместо трёх суток. В том же году в 135 км к северу от города открыли месторождение золота — так начиналась история Многовершинного."],"key":["1955: в городе 38 702 жителя, с пригородной зоной — более 50,5 тыс.","1956: на улице Школьной заселён первый каменный трёхэтажный дом; открыты детская поликлиника, детская больница и женская консультация.","1956: первый вертолёт Ми-1; 1958 — самолёты Ли-2; 1960 — вертолёты Ми-4; 1963 — объединённый авиаотряд с аэропортами северных районов края.","1959: теплоход «Ерофей Хабаров» проходит путь Хабаровск — Николаевск за 40 часов; у горы Многовершинной найдено золото.","1960: судоверфь и судоремонтный завод объединены в судостроительный завод; с 1961 года при нём работает филиал вечернего судостроительного техникума.","1962: Нижнеамурский район упразднён, его территория стала пригородной зоной Николаевска.","1964: «Морской-1» — первый на Дальнем Востоке сухогруз «река — море» (2000 т) — открывает регулярную линию в Японию."],"timeline":[{"year":1954,"id":318,"title":"Энергопоезд со стройки тоннеля на Сахалин"},{"year":1954,"id":322,"title":"Изотоп для контроля сварных швов"},{"year":1954,"id":325,"title":"Детско-юношеская спортивная школа"},{"year":1954,"id":328,"title":"Первая школа в Маго: 19 учеников"},{"year":1954,"id":330,"title":"Пионеры Озерпаха учат взрослых грамоте"},{"year":1955,"id":332,"title":"Город в 1955 году: 38 702 жителя"},{"year":1955,"id":335,"title":"747 квартир за пять лет"},{"year":1956,"id":338,"title":"Первый каменный дом на улице Школьной"},{"year":1956,"id":340,"title":"Детская больница, женская консультация, скважины"},{"year":1956,"id":341,"title":"Медицинское училище"},{"year":1956,"id":342,"title":"Первый вертолёт — «Копеечка»"},{"year":1956,"id":344,"title":"Рейд лесной сплотки в Маго"},{"year":1957,"id":350,"title":"Башенные краны в доке"},{"year":1957,"id":355,"title":"Асфальт, гостиница, чайная и мороженое"},{"year":1958,"id":357,"title":"Судоремонтный завод: свой флот и рационализаторы"},{"year":1958,"id":364,"title":"Станция юных натуралистов"},{"year":1958,"id":368,"title":"Школьная электростанция в Красном"},{"year":1959,"id":372,"title":"«Ерофей Хабаров»: 40 часов от Хабаровска"},{"year":1959,"id":371,"title":"Золото у горы Многовершинной"},{"year":1959,"id":373,"title":"Трёхэтажная школа № 3"},{"year":1960,"id":381,"title":"Гастроном, универмаг и школа № 4"},{"year":1960,"id":383,"title":"40 922 пассажира за год"},{"year":1960,"id":384,"title":"Рождение судостроительного завода и «дорога дружбы»"},{"year":1961,"id":388,"title":"Техникум при заводе"},{"year":1961,"id":394,"title":"Торговля без продавца"},{"year":1962,"id":395,"title":"Нижнеамурский район — пригород Николаевска"},{"year":1962,"id":396,"title":"Электропечь: сталь вместо чугуна"},{"year":1963,"id":402,"title":"Объединённый авиаотряд"},{"year":1963,"id":405,"title":"Энергопоезд даёт городу свет"},{"year":1963,"id":407,"title":"Интернат в селе Красное"},{"year":1963,"id":409,"title":"Многовершинное: зона Главная"},{"year":1964,"id":416,"title":"«Морской-1» идёт в Японию"},{"year":1964,"id":412,"title":"Самостоятельный судостроительный техникум"},{"year":1964,"id":418,"title":"Геологоразведочная партия на Многовершинном"}],"compare":[{"title":"Из Хабаровска — быстрее вдвое","note":"Часов в пути от Хабаровска до Николаевска (первый рейс «Ерофея Хабарова», 1959)","a":{"label":"Пароход","value":72},"b":{"label":"«Ерофей Хабаров»","value":40},"result":"Быстрее в 1,8 раза: 40 часов вместо трёх суток (72 часа).","id":372}],"stack":{"title":"Что сажали в посёлке Маго (1957)","note":"Посевная площадь по культурам, гектаров","unit":" га","parts":[{"label":"Картофель","value":13},{"label":"Овёс","value":8.5},{"label":"Турнепс","value":2.5},{"label":"Кукуруза","value":2},{"label":"Овощи","value":2}],"id":356},"mapLinks":[{"title":"Первый каменный дом (1956)","text":"В 1956 году на улице Школьной построили и заселили первый в городе каменный трёхэтажный дом.","streets":["Школьная улица"]},{"title":"Техникум на улице Кирова (1961)","text":"Филиалу вечернего судостроительного техникума отдали половину здания на улице Кирова, 6.","streets":["улица Кирова"]},{"title":"Юннаты у Чкаловской (1959)","text":"Для секции юных натуралистов отдел образования купил два дома в районе улицы Чкаловской — так появилась станция юннатов.","streets":["Чкаловская улица"]},{"title":"Мыс Кошка (1963)","text":"На мысе Кошка приняли в эксплуатацию плавбазу ремонтно-эксплуатационной базы (РЭБ) флота.","streets":["улица Мыс Кошка"]}],"people":[{"name":"Наум Львович Кунин","role":"Первый директор судостроительного завода","text":"Бывший руководитель судоверфи; в хронологии сказано, что в этой должности он проработал 14 лет и был награждён орденом Ленина. В 1960 году обратился в министерство с просьбой открыть при заводе судостроительный техникум — в 1961-м филиал техникума открылся.","id":384},{"name":"Борис Калмыков и Леонид Писарев","role":"Пилот и авиатехник первого вертолёта","text":"Калмыков пилотировал первый Ми-1 — «Копеечку», Писарев готовил его к полётам. К новой машине сначала относились с недоверием, но вертолёты стали обслуживать геологов, оленеводов и охранять леса от пожаров.","id":342},{"name":"Вера Фёдоровна Сидорова","role":"Заведующая первой школой посёлка Маго","text":"В 1954 году в школе на улице Рейдовой было 19 учеников на все классы. Своих учителей не было — их срочно вызывали из соседних сёл.","id":328},{"name":"Эмма Иннокентьевна Слесаренко","role":"Библиотекарь в Озерпахе","text":"Собрала группу пионеров, которые помогали освоить грамоту не умевшим читать жителям посёлка.","id":330},{"name":"Грачков и Соколкин","role":"Киномеханики кинопередвижки № 487","text":"Комсомольцы, возившие кино в село Красное и Половинку. В соревновании 1959 года заняли первое место по всем показателям.","id":346},{"name":"В. Р. Поликанов","role":"Геолог","text":"В 1959 году впервые установил золотую минерализацию в районе горы Многовершинной.","id":371},{"name":"В. Т. Комаров","role":"Начальник Многовершинной геологоразведочной партии","text":"Партию организовали в конце 1964 года; в верховьях реки Улчонок вырос верхний посёлок геологов.","id":418}],"glossary":[["Энергопоезд","Передвижная электростанция на железнодорожных вагонах. Николаевский энергопоезд пришёл с закрытой стройки тоннеля на Сахалин."],["Контроль сварных швов","Проверка, нет ли внутри шва трещин и пустот. Шов просвечивают излучением радиоактивного изотопа — как рентгеном."],["Электродуговая печь","Печь, где металл плавится от электрической дуги. Позволила заводу лить сталь вместо чугуна."],["Эллинг","Крытое место на берегу, где строят суда, а потом спускают их на воду."],["Судно «река — море»","Судно, которое может ходить и по реке, и по морю: груз не нужно перегружать в устье."],["Рейд морской лесной сплотки","Предприятие, где брёвна связывают в большие плоты (сплотки), чтобы буксировать их по морю."],["Лихтер","Несамоходное грузовое судно для перевозки грузов на буксире или для разгрузки больших судов на рейде."],["Совнархоз","Совет народного хозяйства: в 1957–1965 годах руководил промышленностью области или края вместо министерств."],["Кинопередвижка","Кинопроектор с экраном, который возили по сёлам, где не было кинотеатра."],["Коопзверопромхоз","Кооперативное хозяйство, которое занималось охотой, звероводством и заготовкой пушнины."],["Вечерний техникум","Техникум для работающих: учились после смены, не бросая работу на заводе."]],"quiz":[{"q":"На какой улице в 1956 году заселили первый каменный трёхэтажный дом?","options":["Советской","Ленина","Школьной","Горького"],"a":2,"why":"На улице Школьной. До этого строили одно- и двухэтажные дома.","id":338},{"q":"Как авиаторы ласково называли первый вертолёт Ми-1?","options":["«Копеечка»","«Стрекоза»","«Пчёлка»","«Ласточка»"],"a":0,"why":"«Копеечка». Первым её пилотировал Борис Калмыков.","id":342},{"q":"За сколько часов «Ерофей Хабаров» прошёл от Хабаровска до Николаевска в первом рейсе 1959 года?","options":["12","40","72","100"],"a":1,"why":"За 40 часов. Обычный пароход шёл бы около трёх суток.","id":372},{"q":"Что произошло в 1960 году с судоверфью и судоремонтным заводом?","options":["Их закрыли","Их перенесли в Маго","Их передали пароходству","Их объединили в судостроительный завод"],"a":3,"why":"Их объединили в судостроительный завод; первым директором стал Н. Л. Кунин.","id":384},{"q":"Как назвали дорогу, отсыпанную через заливчик между заводом и верфью?","options":["«Дорога жизни»","«Дорога дружбы»","«Заводской тракт»","«Амурская дамба»"],"a":1,"why":"«Дорога дружбы» — она соединила два объединённых предприятия.","id":384},{"q":"Куда теплоход «Морской-1» возил экспортную древесину?","options":["В Китай","В Корею","В Японию","В США"],"a":2,"why":"В Японию. «Морской-1» открыл регулярную заграничную линию.","id":416},{"q":"Что нашли в 1959 году в 135 км к северу от Николаевска?","options":["Месторождение золота","Нефть","Уголь","Горячие источники"],"a":0,"why":"Золото: в районе горы Многовершинной его впервые установил геолог В. Р. Поликанов.","id":371},{"q":"Что стало с Нижнеамурским районом в 1962 году?","options":["Его разделили на два района","Его упразднили, а территорию присоединили к Николаевску как пригородную зону","Его передали Сахалинской области","Его переименовали"],"a":1,"why":"Район упразднили, вся его территория стала пригородной зоной Николаевска.","id":395}],"tasks":["Найдите на карте улицу Школьную. Почему первый каменный дом — событие для города, где до этого строили из дерева?","Составьте «транспортную ленту» 1950–1964 годов: первый автобус, Ан-2, Ми-1, Ли-2, Ми-4, «Ерофей Хабаров», «Морской-1». Как менялась связь Николаевска с краем и с миром?","Выпишите всё, что открылось для детей в 1954–1964 годах: школы, спортшкола, станция юннатов, интернаты. Сравните со списком из главы 1946–1953.","В 1954 году пионеры Озерпаха учили взрослых читать. Почему, как вы думаете, в 1950-х ещё были неграмотные взрослые? Кто и где мог научить их грамоте?","Золото у горы Многовершинной нашли в 1959 году, партию геологов создали в 1964-м. Что должно произойти, чтобы находка геологов стала рудником и посёлком?"],"sources":["Текст записей — хронология автора проекта.","Есть воспоминания и рассказы о школах и библиотеках района (Маго, Озерпах, село Красное).","Источники по каждой записи уточняются; список проверки — data/vychitka_growth.csv."]},"builders":{"slug":"builders","from":1965,"to":1975,"kicker":"Глава 5 · 1965–1975","title":"Вода, тепло и свет","subtitle":"Городской водопровод, ТЭЦ, скоростные «Метеоры» на Амуре и посёлки геологов у горы Многовершинной","intro":["Эти годы принесли в дома удобства «большого города». В 1965–1966 годах сдали первую очередь городского водопровода. В 1967-м началось строительство Николаевской ТЭЦ, а в 1973–1975 годах она вошла в строй: три котла первой очереди сменили мелкие ведомственные электростанции, и начали тепло подводить к жилым кварталам. В 1971 году заработала станция «Орбита», которая принимала телевидение из Москвы через космос.","Судостроительный завод переходил на современное производство. В 1967 году сдали вторую очередь эллинга: основная часть работ ушла под крышу, заработали механизированные линии. Завод строил рыболовецкие сейнеры РС-300; сейнер «Умелец» в 1970 году за сезон добыл 65 000 центнеров рыбы — всесоюзный рекорд для судов этого типа. Всего таких сейнеров построили больше 200. Рос и порт Маго (212 тысяч тонн груза в 1970 году), а в 1975-м закончили круглогодичную дорогу Маго — Николаевск длиной 45 км.","Расстояния сокращались. С 1967 года по Амуру пошли скоростные «Метеоры», и путь от Хабаровска сократился вдвое. К 1965 году объём авиационных работ вырос в 80 раз по сравнению с 1948-м, а в 1971-м над городом появился вертолёт Ми-8. На карте района появлялись новые места: в 1967 году основали посёлок геологов у Многовершинного месторождения, село Красное приняло базу Нижнеамурской геологоразведочной экспедиции, а в 1974-м Маго стало посёлком городского типа. В городе открылся районный Дом культуры (1968), а в 1975 году — краеведческий музей в новом здании на улице Гоголя, к 125-летию города."],"key":["1965–1966: сдана первая очередь городского водопровода.","1967: начато строительство ТЭЦ; в 1973–1975 годах вступают в строй три котла первой очереди, начинается теплофикация кварталов.","1967: на линии Хабаровск — Николаевск скоростные «Метеоры» сокращают время в пути вдвое.","1968: открыт районный Дом культуры; 1971: станция «Орбита» принимает телевидение из Москвы.","1970: сейнер РС-300 «Умелец» ставит всесоюзный рекорд — 65 000 центнеров рыбы за сезон.","1975: закончена круглогодичная дорога Маго — Николаевск (45 км); музей открыт в новом здании на улице Гоголя."],"timeline":[{"year":1965,"id":424,"title":"Первая очередь водопровода"},{"year":1965,"id":422,"title":"Центральная городская библиотека"},{"year":1965,"id":427,"title":"Ширпотреб на судозаводе: от почтовых ящиков до мебели"},{"year":1965,"id":431,"title":"Многовершинная партия начинает разведку"},{"year":1965,"id":430,"title":"Озерпах: дома, сосны и будущий водопровод"},{"year":1966,"id":433,"title":"Первый выпуск судостроительного техникума"},{"year":1966,"id":437,"title":"Швартовые испытания — прямо на стапеле"},{"year":1967,"id":439,"title":"Эллинг: судостроение уходит под крышу"},{"year":1967,"id":441,"title":"Детский кинотеатр «Пионер»"},{"year":1967,"id":443,"title":"Сейнеры РС-300"},{"year":1967,"id":446,"title":"«Метеор» сокращает путь вдвое"},{"year":1967,"id":447,"title":"Начало стройки ТЭЦ"},{"year":1967,"id":448,"title":"«Лучшая библиотека РСФСР» — в Озерпахе"},{"year":1967,"id":449,"title":"Посёлок геологов на Многовершинном"},{"year":1967,"id":450,"title":"Красное — «геологическое время»"},{"year":1968,"id":456,"title":"Открыт районный Дом культуры"},{"year":1968,"id":457,"title":"База отдыха и диетическое питание на заводе"},{"year":1968,"id":458,"title":"Колхоз «Ленинец» растёт"},{"year":1969,"id":459,"title":"Агентство «Аэрофлота»"},{"year":1969,"id":460,"title":"Николаевский леспромхоз"},{"year":1969,"id":467,"title":"Гостиница «Север» на 90 мест"},{"year":1969,"id":465,"title":"Рейд в Маго: экспортный лес"},{"year":1970,"id":471,"title":"Сейнер «Умелец» — всесоюзный рекорд"},{"year":1970,"id":474,"title":"Военно-спортивный лагерь «Подвиг»"},{"year":1970,"id":480,"title":"Порт Маго: 212 тысяч тонн"},{"year":1970,"id":481,"title":"Геологи переезжают в Красное"},{"year":1971,"id":482,"title":"«Орбита»: Москва на экране"},{"year":1971,"id":484,"title":"Вертолёт Ми-8"},{"year":1971,"id":483,"title":"Асфальтный завод"},{"year":1972,"id":490,"title":"Музей переезжает на улицу Гоголя"},{"year":1972,"id":493,"title":"Овсяное поле: стройотряд и улица Студенческая"},{"year":1972,"id":492,"title":"Здравоохранение города и района"},{"year":1973,"id":495,"title":"Первая очередь ТЭЦ"},{"year":1973,"id":497,"title":"Плавдок для РЭБ флота"},{"year":1973,"id":499,"title":"Скоростная линия Комсомольск — Николаевск"},{"year":1973,"id":500,"title":"Хабаровск — Охотск: 1500 километров"},{"year":1973,"id":501,"title":"Николаевск — победитель по благоустройству"},{"year":1973,"id":505,"title":"Маго глазами очевидца"},{"year":1974,"id":508,"title":"Сварочный автомат ТС-32"},{"year":1974,"id":509,"title":"Маго — посёлок городского типа"},{"year":1974,"id":518,"title":"Воздушный мост Вершинка — Красное"},{"year":1975,"id":528,"title":"Третий котёл ТЭЦ"},{"year":1975,"id":529,"title":"Площадь Победы"},{"year":1975,"id":526,"title":"Дорога Маго — Николаевск"},{"year":1975,"id":527,"title":"Буровые вышки на базе тримаранов"},{"year":1975,"id":531,"title":"Связь: радиоточки и АТС"},{"year":1975,"id":532,"title":"Школа в Многовершинном становится средней"}],"compare":[{"title":"Читателей стало в 1,6 раза больше","note":"Читатели в библиотеках города и района, тысяч человек","a":{"label":"1965","value":16.7},"b":{"label":"1971","value":26.8},"id":486}],"stack":{"title":"Кто лечит: медицинские работники города и района (1972)","note":"Работников по группам","unit":" чел.","parts":[{"label":"Врачи","value":120},{"label":"Зубные врачи","value":14},{"label":"Средний медицинский персонал","value":570}],"id":492},"mapLinks":[{"title":"Музей на улице Гоголя (1972–1975)","text":"Переезд музея в новое помещение на улице Гоголя, 27-а растянулся на два с лишним года: трудности с транспортом, ремонтом и оформлением экспозиций. Открылся он в августе 1975 года, к 125-летию города, и пока только нижние залы.","streets":["улица Гоголя"]},{"title":"Красное — «геологическое время»","text":"В 1967 году село приняло базу Нижнеамурской геологоразведочной экспедиции: началось бурное жилищное строительство, появились благоустроенные дома, общежитие, Дом культуры.","places":["Красное"]},{"title":"Маго: порт, рейд и дорога","text":"Порт Маго и Нижнеамурский рейд работали на экспорт леса; в 1970 году порт обработал 212 тысяч тонн груза, а в 1974-м Маго стало посёлком городского типа.","places":["Маго"]}],"people":[{"name":"Василий Васильевич Гагарин","role":"Краснодеревщик судостроительного завода","text":"Когда завод начал делать ширпотреб — от почтовых ящиков до мебели, — появились свои мастера-краснодеревщики. Гагарин стал одним из первых.","id":427},{"name":"Владимир Иванович Галкин","role":"Первый руководитель агентства «Аэрофлота»","text":"Возглавил агентство в 1969 году; стоял у истоков военно-спортивного лагеря «Подвиг» имени Героя Советского Союза Г. Е. Попова.","id":459},{"name":"Михаил Ильич Скороход","role":"Директор асфальтного завода","text":"Асфальтный завод построили в 1971 году, а запустили в следующем.","id":483},{"name":"Виктор Алексеевич Кайдалов","role":"Главный геолог Нижнеамурской экспедиции","text":"Из его воспоминаний известно, почему в 1967 году школу села Красное перенесли в двухэтажное здание казармы на берегу Нижней Патхи: сгорела мастерская, а детей стало слишком много.","id":452},{"name":"Эрик Петрович Хохлов","role":"Главный геолог, первооткрыватель Многовершинного","text":"Центральная улица двухэтажных благоустроенных кирпичных домов в селе Красное названа его именем.","id":517},{"name":"В. И. Поддубнова","role":"Директор школы в посёлке Многовершинный","text":"В 1975 году восьмилетняя школа посёлка была реорганизована в среднюю — во главе с Поддубновой.","id":532}],"glossary":[["ТЭЦ","Теплоэлектроцентраль: станция, которая вырабатывает и электричество, и тепло для отопления домов."],["Теплофикация","Отопление домов теплом от одной станции — вместо множества маленьких котельных и печей."],["«Метеор»","Скоростное пассажирское судно на подводных крыльях: в движении корпус поднимается над водой."],["«Орбита»","Система телевизионной связи через спутник: сигнал из Москвы принимали в далёких городах."],["НОТ","Научная организация труда: расчёты и опыты, чтобы рабочее место было удобным, а работа — быстрее и безопаснее."],["Ширпотреб","Товары широкого потребления: мебель, почтовые ящики, палатки, рюкзаки и подобное."],["Швартовые испытания","Проверка судна у причала или на стапеле — до выхода в море: работают ли механизмы и системы."],["Посёлок городского типа","Крупный посёлок с городской инфраструктурой; в хронологии таким становится Маго."],["Геологоразведочная партия","Отряд геологов, который ищет и оценивает месторождения: бурит, берёт пробы, подсчитывает запасы."],["Плавдок","Плавучий док: сооружение, которое погружается, принимает судно и поднимает его из воды для ремонта."]],"quiz":[{"q":"Что в 1965–1966 годах сдали в эксплуатацию — первой очередью?","options":["Метро","Городской водопровод","Трамвайную линию","Речной вокзал"],"a":1,"why":"Первую очередь городского водопровода; в 1965 году её только сдавали, а в 1966-м сдали окончательно.","id":438},{"q":"Какие сейнеры с 1967 года начали строить на судостроительном заводе?","options":["РС-300","«Сахалин»","«Астраханка»","МДС"],"a":0,"why":"Рыболовецкие сейнеры РС-300 с неограниченным районом плавания; позже завод построил более 200 таких судов.","id":443},{"q":"Во сколько раз сократилось время плавания Хабаровск — Николаевск с вводом «Метеора» в 1967 году?","options":["В 2 раза","В 10 раз","На 5 %","Не изменилось"],"a":0,"why":"В два раза: скоростные линии на теплоходе «Метеор» сократили время в пути.","id":446},{"q":"Как называлась станция, принимавшая через космос телесигнал из Москвы?","options":["«Радуга»","«Орбита»","«Экран»","«Заря»"],"a":1,"why":"Телевизионная станция «Орбита» вступила в строй в 1971 году.","id":482},{"q":"Сколько центнеров рыбы добыла за сезон команда сейнера «Умелец» в 1970 году?","options":["650","6 500","65 000","650 000"],"a":2,"why":"65 000 центнеров — всесоюзный рекорд для судов этого типа.","id":471},{"q":"Кто был первым руководителем агентства «Аэрофлота» в Николаевске (1969 год)?","options":["Сергей Ерлыкин","Виктор Кравец","Владимир Галкин","Александр Самсонов"],"a":2,"why":"Владимир Иванович Галкин. Ерлыкин и Кравец руководили авиаотрядами раньше, Самсонов — объединённым отрядом в 1963-м.","id":459},{"q":"Что вводилось в строй в 1973–1975 годах и сменило мелкие ведомственные электростанции?","options":["ГЭС","АЭС","ТЭЦ","Ветростанция"],"a":2,"why":"Николаевская ТЭЦ: первую очередь пускали в 1973-м, а третий котёл вошёл в строй в 1975-м.","id":495},{"q":"К какому юбилею города в 1975 году открылся музей в новом здании на улице Гоголя?","options":["К 100-летию","К 125-летию","К 50-летию Советской власти","К 30-летию Победы"],"a":1,"why":"К 125-летию города. Открылись только нижние залы: верхний зал так и не оформили руководители предприятий.","id":490}],"tasks":["Составьте схему «Вода, тепло, свет»: что в 1965–1975 годах приходит в дома жителей (водопровод, тепло от ТЭЦ, телевидение, радиоточки). Как изменилась повседневная жизнь?","Найдите на карте улицу Гоголя. Почему переезд музея растянулся на два с лишним года? Что нужно сделать, чтобы переехать музею?","Сравните Красное и Маго из блока «На карте». Как геологоразведка и порт по-разному меняли посёлки?","Прочитайте запись 1973 года о Маго («товарно-продуктовый рай»). Какие слова в ней — факты (баня, пиво в буфете, мясо, фрукты, брусника), а какие — оценка автора? Как проверить такие воспоминания?","Посчитайте: в 1965 году читателей было 16,7 тысяч, в 1971-м — 26,8 тысяч. Во сколько раз выросло число читателей? Какие ещё цифры в этой главе показывают рост?"],"sources":["Текст записей — хронология автора проекта.","В записях есть воспоминания очевидцев (в том числе главного геолога В. А. Кайдалова) и справка горспортсоюза 1967 года.","Источники по каждой записи уточняются; список проверки — data/vychitka_builders.csv."]},"shipyard":{"slug":"shipyard","from":1976,"to":1985,"kicker":"Глава 6 · 1976–1985","title":"Суда для всей страны","subtitle":"Расцвет судостроительного завода, «Мобиль» и новые районы города, ЛЭП на север и золото Многовершинного","intro":["Судостроительный завод стал градообразующим предприятием: на судостроение и судоремонт приходилось больше половины промышленного производства города. С 1978 года завод построил 108 сейнеров-траулеров типа «Сахалин», а в 1976–1987 годах — 10 сторожевых кораблей. Суда строили и для Японии, Индонезии, Алжира, Египта и Кубы, а для Вьетнама — блок-модули буровой платформы. В 1977 году в городе появилась первая «высотка» — девятиэтажный инженерный корпус завода с электронно-вычислительной машиной, а в 1981-м построили новый эллинг больше 12 тысяч квадратных метров: суда больше не надо достраивать во Владивостоке.","Город строился. В 1977 году около 4000 семей жили в благоустроенных квартирах, в 1979-м сдали 120-квартирный дом на улице Школьной, а в 1984-м запустили завод крупнопанельного домостроения «Мобиль» — третий такой в стране, способный давать до 50 тысяч квадратных метров жилья в год. К городской ТЭЦ подключали жилые дома, а в 1983-м ввели вторую очередь станции. Открывались поликлиники, ясли-сады, школы в Маго и Иннокентьевке. В 1985 году заработали центральная районная больница и плавательный бассейн с восемью дорожками, а зимой горожане катались на лыжной базе «Старт».","Север становился ближе. С 1981 года в Многовершинный летали регулярные рейсы, в 1985-м туда дошла 136-километровая ЛЭП — самая северная в Хабаровском крае, и создали Нижнеамурский горно-обогатительный комбинат. В 1984 году на линию Хабаровск — Николаевск вышел «Метеор-178», которому нужно 28 часов, а на смену знаменитым Ан-2 пришли чехословацкие Л-410."],"key":["1976–1987: завод построил 10 сторожевых кораблей; с 1978 года — 108 сейнеров-траулеров типа «Сахалин».","1977: первая «высотка» — 9-этажный инженерный корпус судозавода с ЭВМ; открыта лыжная база «Старт».","1981: новый эллинг — суда сдают заказчику у своего причала, без достройки во Владивостоке.","1984: запущен завод «Мобиль» — до 50 тысяч квадратных метров жилья в год.","1984: «Метеор-178» доставляет пассажиров из Хабаровска за 28 часов; вместо Ан-2 — Л-410.","1985: ЛЭП на север длиной 136 км, создан горно-обогатительный комбинат, открыта центральная районная больница."],"timeline":[{"year":1976,"id":536,"title":"Станок с программным управлением"},{"year":1976,"id":539,"title":"Автоколонна по льду Амура: Николаевск — Хабаровск"},{"year":1976,"id":541,"title":"Музыкальная школа в Маго"},{"year":1976,"id":542,"title":"Дорога к Многовершинному связала Чля с городом"},{"year":1977,"id":544,"title":"Медучилище — в новом здании"},{"year":1977,"id":547,"title":"Детская поликлиника на 7 тысяч детей"},{"year":1977,"id":549,"title":"Лыжная база «Старт»"},{"year":1977,"id":550,"title":"Первая «высотка» и ЭВМ"},{"year":1977,"id":555,"title":"Порт и лесотарный комбинат в Маго объединили"},{"year":1977,"id":556,"title":"Красносельская школа — десятилетняя"},{"year":1978,"id":560,"title":"Кран «Фламинго» на стапельной площадке"},{"year":1978,"id":561,"title":"Новая специальность по заказу завода"},{"year":1978,"id":565,"title":"Суда для Японии, Индонезии, Алжира, Египта, Кубы"},{"year":1978,"id":563,"title":"Овсяное поле: библиотека и клуб"},{"year":1979,"id":567,"title":"Ясли-сад «Мишутка»"},{"year":1979,"id":568,"title":"Дом на улице Школьной"},{"year":1979,"id":570,"title":"Теплосеть и вторая очередь ТЭЦ"},{"year":1979,"id":572,"title":"Школа в Многовершинном"},{"year":1979,"id":574,"title":"Красносельская библиотека — в цоколе нового дома"},{"year":1979,"id":577,"title":"Николаевск — город двух портов"},{"year":1980,"id":587,"title":"Комбинат начинает освоение Многовершинного"},{"year":1980,"id":588,"title":"Горнолыжная трасса к Олимпиаде-80"},{"year":1981,"id":592,"title":"Новый эллинг: суда сдают у своего причала"},{"year":1981,"id":590,"title":"Первая категория качества для «Сахалина»"},{"year":1981,"id":593,"title":"Авиарейсы в Многовершинный"},{"year":1982,"id":602,"title":"Дом культуры в селе Красное"},{"year":1982,"id":600,"title":"ЛЭП до Многовершинного через Чля"},{"year":1982,"id":598,"title":"ТЭЦ — трижды первая во Всесоюзном соревновании"},{"year":1983,"id":609,"title":"Вторая очередь ТЭЦ"},{"year":1983,"id":608,"title":"Баржа для строителей Бурейской ГЭС"},{"year":1983,"id":607,"title":"Самоцветы в Каменке"},{"year":1983,"id":611,"title":"Жильё, дороги и теплотрасса: итоги десяти лет"},{"year":1984,"id":612,"title":"Завод «Мобиль»"},{"year":1984,"id":613,"title":"Садовые домики с судозавода"},{"year":1984,"id":614,"title":"Л-410 вместо Ан-2"},{"year":1984,"id":617,"title":"«Метеор-178»: 28 часов из Хабаровска"},{"year":1984,"id":619,"title":"Красное: улица Победы"},{"year":1985,"id":620,"title":"Центральная районная больница"},{"year":1985,"id":626,"title":"Бассейн 8 × 25 метров"},{"year":1985,"id":627,"title":"Создан горно-обогатительный комбинат"},{"year":1985,"id":628,"title":"ЛЭП на север: 136 километров"},{"year":1985,"id":629,"title":"Школа № 3 в Маго"},{"year":1985,"id":622,"title":"«Девятиэтажка» для заводчан"},{"year":1985,"id":635,"title":"Краны «Сокол» и реконструкция базы"}],"compare":[{"title":"Хабаровск — Николаевск: всё короче","note":"Часов в пути от Хабаровска до Николаевска","items":[{"label":"Пароход","value":72},{"label":"1959, «Ерофей Хабаров»","value":40},{"label":"1984, «Метеор-178»","value":28}],"result":"Путь стал короче в 2,6 раза: от трёх суток на обычном пароходе до 28 часов на «Метеоре».","id":617}],"stack":{"title":"Заказы судостроительного завода","note":"Построено единиц: сейнеры-траулеры — с 1978 года, сторожевые корабли — в 1976–1987 годах","unit":" шт.","parts":[{"label":"Сейнеры-траулеры типа «Сахалин»","value":108},{"label":"Сторожевые корабли","value":10}],"id":565},"mapLinks":[{"title":"Дом на улице Школьной (1979)","text":"В 1979 году на улице Школьной приняли в эксплуатацию 120-квартирный дом: в нём общежитие на 200 человек и 60 квартир для малосемейных.","streets":["Школьная улица"]},{"title":"Маго: Овсяное поле, школы и клубы","text":"В микрорайоне Овсяное поле (Маго) открыли библиотеку (1978), клуб (1982) и школу № 3 (1985); в 1979 году построили здание поселкового Совета.","places":["Маго"]},{"title":"Красное: Дом культуры и лаборатории","text":"В 1982 году в селе ввели Дом культуры на 200 мест, а в 1985-м — новую лабораторию для геологоразведочной экспедиции.","places":["Красное"]}],"people":[{"name":"Эрик Петрович Хохлов","role":"Главный геолог, первооткрыватель Многовершинного","text":"В 1979 году в записях о селе Красное сказано: главная улица названа его именем — в честь первооткрывателя золоторудного месторождения Многовершинного.","id":583},{"name":"Сурен Саркисович Дарбинян","role":"Начальник экспедиции «Далькварцсамоцветы», почётный гражданин","text":"Экспедиция построила в Красном контору, общежитие, столовую, бассейн с сауной, котельную и мост через Патху; одна из улиц села носит его имя.","id":583},{"name":"Юные хоккеисты","role":"Команда детского клуба морского порта","text":"В 1985 году в городе впервые прошёл финал краевых соревнований на приз клуба «Золотая шайба»; нашу команду представлял детский клуб морского порта.","id":624}],"glossary":[["Сейнер-траулер","Рыболовное судно, которое ловит рыбу и неводом (как сейнер), и тралом (как траулер)."],["Крупнопанельное домостроение","Дома собирают из готовых бетонных панелей, которые делают на заводе, — стройка идёт быстро."],["ЭВМ","Электронно-вычислительная машина — так называли компьютеры. ЕС-1022 — модель единой серии, занимавшая целую комнату."],["Эллинг","Крытое место на берегу, где строят суда, а потом спускают их на воду."],["Блок-модуль","Крупная готовая часть конструкции. Для Вьетнама делали блок-модули — верхние строения буровой платформы."],["ГОК","Горно-обогатительный комбинат: добывает руду и извлекает из неё металл; в хронологии — комбинат на Многовершинном."],["ЛЭП","Линия электропередачи: провода, по которым ток идёт от станции к потребителям."],["Л-410","Чехословацкий турбовинтовой самолёт для местных авиалиний; в 1984 году пришёл на смену Ан-2."],["Самоцветы","Полудрагоценные камни, которые добывают и обрабатывают для украшений и сувениров."],["Пятилетка","Пятилетний план развития хозяйства СССР; итоги работы подводили по пятилеткам."]],"quiz":[{"q":"Как назывался тип сейнеров-траулеров, серийно строившихся на заводе с 1978 года?","options":["«Волга»","«Сахалин»","«Ангара»","«Амур»"],"a":1,"why":"Сейнеры-траулеры типа «Сахалин»; в 1981 году им присвоили первую категорию качества.","id":565},{"q":"Сколько сейнеров-траулеров типа «Сахалин» построили с 1978 года?","options":["18","48","108","508"],"a":2,"why":"108 сейнеров-траулеров. Кроме них — 10 сторожевых кораблей за 1976–1987 годы.","id":565},{"q":"Сколько этажей было в первой «высотке» города (1977 год)?","options":["5","9","12","16"],"a":1,"why":"9 этажей — инженерный корпус судостроительного завода; в нём смонтирована ЭВМ ЕС-1022.","id":550},{"q":"Сколько квадратных метров жилья в год мог давать завод «Мобиль»?","options":["5 тысяч","50 тысяч","500 тысяч","5 миллионов"],"a":1,"why":"До 50 тысяч квадратных метров — как десять стоквартирных домов. Это был третий такой завод в стране.","id":612},{"q":"Какой самолёт пришёл на смену Ан-2 в 1984 году?","options":["Ту-154","Л-410УВП","Ил-14","Ан-24"],"a":1,"why":"Чехословацкие турбовинтовые самолёты Л-410УВП и Л-410УВП Э.","id":614},{"q":"За сколько часов «Метеор-178» вёз пассажиров из Хабаровска в Николаевск (1984 год)?","options":["8","28","40","72"],"a":1,"why":"28 часов; на борту — 120 пассажиров. В 1959 году «Ерофей Хабаров» шёл 40 часов, а обычный пароход — три суток.","id":617},{"q":"Куда в 1985 году протянули самую северную в Хабаровском крае ЛЭП длиной 136 километров?","options":["В Охотск","В посёлок Многовершинный","В Аян","На Сахалин"],"a":1,"why":"В посёлок Многовершинный — для нового рудника и посёлка горняков.","id":628},{"q":"Что открыли в 1977 году для зимнего отдыха горожан?","options":["Ледовую арену","Лыжную базу «Старт»","Аквапарк","Ипподром"],"a":1,"why":"Лыжную базу «Старт»: освещённая лыжероллерная трасса, бугельный подъёмник, прокат 700 пар лыж.","id":549}],"tasks":["Составьте список стран-заказчиков судостроительного завода (Япония, Индонезия, Алжир, Египет, Куба, Вьетнам). Найдите их на карте мира. Почему завод на Нижнем Амуре получал такие заказы?","Сравните три числа в блоке «Хабаровск — Николаевск: всё короче» (72 → 40 → 28 часов). Что менялось в технике речного транспорта?","Завод «Мобиль» мог давать 50 тыс. кв. м жилья в год — «десять стоквартирных домов». Проверьте: сколько это квартир в год? Сколько семей могло бы переехать в новые дома?","Прочитайте запись 1980 года: «при плане 32 310 тыс. рублей продукции выпущено на 326 919 тыс. рублей» и «выполнен на 100,9 %». Что в этих числах вызывает сомнение? Как проверить?","Как жизнь села Красное менялась благодаря геологам и экспедициям в 1967–1985 годах? Составьте список новых объектов (жильё, школа, Дом культуры, лаборатории)."],"sources":["Текст записей — хронология автора проекта.","В записях есть цифры, требующие проверки (например, 1980 год: план и выпуск продукции; 1985 год: число коек) — см. data/zamechaniya_vychitka.md.","Источники по каждой записи уточняются; список проверки — data/vychitka_shipyard.csv."]},"foundation":{"slug":"foundation","from":1918,"to":1940,"kicker":"Глава 1 · 1918–1940","title":"Заново, с нуля","subtitle":"Как Николаевск после интервенции обзаводился школами, связью, авиацией и судоверфью и стал областным центром","intro":["После интервенции город был маленьким. В 1922 году в нём насчитывали 5,1 тысячи жителей (годом раньше — около тысячи), в уездно-городской больнице было десять коек и один врач. Но за считанные годы открылись школа на 406 учеников, городская библиотека, ЗАГС, первые избы-читальни, заработала временная телефонная связь. В 1923 году учредили Николаевский морской порт и начали восстанавливать его мастерские: к 1927 году корабелы могли сами ремонтировать все суда, приписанные к Николаевску.","Город налаживал связь с миром. В 1924 году смонтировали радиостанцию, вышел первый номер ежедневной газеты «Красный Усть-Амурец» (позже — «Красный маяк»), в Маго начали экспортировать лес, а в 1925-м туда пришёл первый японский лесовоз. В 1929 году в Николаевск прилетел «Страна Советов», доставив первую в истории города авиапочту, а в 1930-м открылась воздушная линия Хабаровск — Оха, начало островной авиации. В 1931 году появился гидроаэропорт (зимой самолёты садились на лёд Амура).","В 1934 году создали Нижнеамурскую область с центром в Николаевске; население города превысило дореволюционный максимум — 16,5 тысячи человек. В том же году родилось авиапредприятие, открылась первая полная средняя школа, а к концу 1930-х работали профессиональный драматический театр (1937), морское пароходство (1939) и медицинское училище (1939). В 1937 году начали строить судоверфь, а в 1940-м она вступила в строй: заложили первое судно — деревянный катер «Димитров»."],"key":["1922: в городе 5,1 тыс. жителей; открыты школа на 406 учеников, библиотека, ЗАГС.","1923: учреждён Николаевский морской порт; к 1927 году корабелы сами ремонтируют все суда Николаевска.","1924–1925: радиостанция, газета «Красный Усть-Амурец», первый японский лесовоз в Маго.","1929–1934: «Страна Советов» привозит первую авиапочту, открывается гидроаэропорт, рождается авиапредприятие.","1934: создана Нижнеамурская область с центром в Николаевске; в городе 16,5 тыс. жителей — больше, чем до революции.","1937–1940: строится судоверфь; в 1939 создано морское пароходство; в 1940 заложено первое судно."],"timeline":[{"year":1918,"id":1,"title":"Школа в селе Красное"},{"year":1919,"id":2,"title":"Иностранная интервенция"},{"year":1921,"id":3,"title":"Школы в Керби и на Весёлой Горке"},{"year":1922,"id":4,"title":"Открылась школа на 406 учеников"},{"year":1922,"id":6,"title":"Библиотека и первые избы-читальни"},{"year":1922,"id":7,"title":"Первая телефонная связь"},{"year":1922,"id":9,"title":"Больница на 10 коек и один врач"},{"year":1923,"id":14,"title":"Три школы первой ступени и средняя школа"},{"year":1923,"id":15,"title":"Учреждён Николаевский морской порт"},{"year":1923,"id":16,"title":"Первая национальная школа — в стойбище Чардбах"},{"year":1924,"id":18,"title":"Временная электростанция"},{"year":1924,"id":19,"title":"Телефонные линии до фарватеров"},{"year":1924,"id":24,"title":"Первая ежедневная газета"},{"year":1924,"id":28,"title":"Радиостанция принимает столицы Европы"},{"year":1924,"id":29,"title":"Комсомольская ячейка в селе Красное"},{"year":1924,"id":32,"title":"Маго становится портом: лес на экспорт"},{"year":1925,"id":33,"title":"Кружок радиолюбителей"},{"year":1925,"id":45,"title":"Первый японский лесовоз в Маго"},{"year":1925,"id":38,"title":"Школа для детей корейцев"},{"year":1925,"id":43,"title":"Городской Совет"},{"year":1926,"id":49,"title":"Нижнеамурский округ"},{"year":1926,"id":52,"title":"Педагогическое училище"},{"year":1926,"id":50,"title":"Перепись: неграмотных детей всё меньше"},{"year":1926,"id":58,"title":"Рыбокомбинат Озерпах"},{"year":1927,"id":60,"title":"Корабелы ремонтируют все суда сами"},{"year":1928,"id":66,"title":"Горбуша — в Гамбург"},{"year":1929,"id":67,"title":"Нижне-Амурский рыбопромышленный трест"},{"year":1929,"id":69,"title":"«Страна Советов» в Николаевске"},{"year":1929,"id":70,"title":"Первая авиапочта"},{"year":1930,"id":74,"title":"Воздушная линия Хабаровск — Оха"},{"year":1930,"id":75,"title":"Обязательное начальное обучение"},{"year":1930,"id":80,"title":"Школьные завтраки: хлеб, сахар, масло, икра"},{"year":1930,"id":82,"title":"Рыболовецкий колхоз в Красном"},{"year":1931,"id":88,"title":"Гидроаэропорт: зимой — на лёд Амура"},{"year":1931,"id":89,"title":"Театр рабочей молодёжи (ТРАМ)"},{"year":1932,"id":94,"title":"Кинотеатр «Глобус»"},{"year":1932,"id":95,"title":"Педтехникум переезжает в Николаевск"},{"year":1933,"id":100,"title":"Регулярные рейсы Хабаровск — Николаевск"},{"year":1933,"id":104,"title":"Драга на приисках Херпучей"},{"year":1934,"id":105,"title":"Родилось Николаевское авиапредприятие"},{"year":1934,"id":106,"title":"Создана Нижнеамурская область"},{"year":1934,"id":108,"title":"Первый областной Съезд Советов"},{"year":1934,"id":110,"title":"Первая полная средняя школа"},{"year":1934,"id":111,"title":"Рудник на Белой Горе: село Чля растёт"},{"year":1935,"id":122,"title":"Посевная кампания области: 3 464 гектара"},{"year":1936,"id":125,"title":"Первый сезон на Анненских водах"},{"year":1937,"id":130,"title":"Профессиональный драматический театр"},{"year":1937,"id":136,"title":"Начало строительства судоверфи"},{"year":1937,"id":129,"title":"Заказы для будущего судозавода"},{"year":1938,"id":140,"title":"Овоще-молочный совхоз"},{"year":1938,"id":144,"title":"Заработок рыбака вырос вдвое"},{"year":1939,"id":146,"title":"Морской порт и морское пароходство"},{"year":1939,"id":145,"title":"Медицинское училище"},{"year":1939,"id":148,"title":"Хлебозавод"},{"year":1939,"id":161,"title":"Вклады в сберкассах"},{"year":1939,"id":171,"title":"Планы третьей пятилетки"},{"year":1940,"id":172,"title":"Судоверфь вступила в строй: катер «Димитров»"},{"year":1940,"id":173,"title":"Школа № 4"},{"year":1940,"id":175,"title":"Три газеты"}],"compare":[{"title":"Больница растёт","note":"Коек в городской больнице","items":[{"label":"1922","value":10},{"label":"1923","value":20},{"label":"1930","value":65}],"result":"За восемь лет коечный фонд вырос в 6,5 раза (с 10 до 65 коек).","id":78}],"stack":{"title":"Скот и олени области (1937)","note":"Поголовье, тысяч голов","unit":" тыс.","parts":[{"label":"Северные олени","value":48.2},{"label":"Свиньи","value":7.4},{"label":"Крупный рогатый скот","value":7.1},{"label":"Лошади","value":5.6}],"id":132},"mapLinks":[{"title":"Улица Кантера","text":"В 1934 году первым председателем областного исполкома стал Оскар Кристапович Кантер. Найдите на карте улицу Кантера и выясните: в честь кого она названа?","streets":["улица Кантера"]},{"title":"Музей на улице Горького, 114 (1940)","text":"В 1940 году краеведческому музею выделили здание на улице Горького, 114; в коллекции было 747 экспонатов.","streets":["улица Горького"]},{"title":"Маго: лес на экспорт","text":"С 1924–1925 годов в Маго организовали экспорт леса, а в 1925-м пришёл первый японский лесовоз.","places":["Маго"]},{"title":"Красное: школа, колхоз и комсомольцы","text":"В селе Красное в 1918 году открыли трёхклассную школу, в 1924-м организовали комсомольскую ячейку, а в 1930–1931 годах — рыболовецкий колхоз «Красный восход».","places":["Красное"]},{"title":"Чля: рудник на Белой Горе","text":"В 1934 году на Белой Горе открыли рудник и фабрику, село Чля выросло, а в 1939-м получило статус рабочего посёлка.","places":["Чля"]}],"people":[{"name":"Варвара Гавриловна Селезнёва","role":"Учительница села Красное","text":"Приехала в 1918 году в трёхклассную школу — энергичная, строгая, хорошо знавшая своё дело. Три года обучала детей грамоте.","id":1},{"name":"Дмитрий Кочергин, Виктор Евсюков, Анна Ступина, Иван Нелюбов","role":"Первые комсомольцы села Красное","text":"В 1924 году создали комсомольскую ячейку из четырёх человек. Вечера с докладами проходили в избе-читальне; здесь же работала школа ликбеза.","id":29},{"name":"С. А. Шестаков, Ф. Е. Болотов, Б. В. Стерлигов, Д. В. Фуфаев","role":"Экипаж самолёта «Страна Советов»","text":"Летели по маршруту Москва — Дальний Восток — Нью-Йорк; в 1929 году впервые привезли в Николаевск авиапочту. Встречать самолёт пришло почти всё население города.","id":69},{"name":"М. В. Водопьянов","role":"Полярный лётчик, Герой Советского Союза","text":"В 1930 году совершил первый транспортный рейс по воздушной линии Хабаровск — Оха-на-Сахалине через Николаевск; так началась островная авиация.","id":74},{"name":"И. В. Черненко","role":"Первый руководитель авиазвена","text":"8 августа 1934 года — официальная дата рождения Николаевского авиапредприятия. Три самолёта Ш-2 могли брать на борт до 200 кг груза.","id":105},{"name":"Оскар Кристапович Кантер","role":"Первый председатель облисполкома","text":"Возглавлял организационный комитет Нижнеамурской области и после первого областного Съезда Советов (12–14 октября 1934 года) стал первым председателем облисполкома.","id":108},{"name":"Кузьма Дмитриевич Кузнецов","role":"Начальник строительства судоверфи","text":"В 1937 году в город прибыла первая группа рабочих — 150 человек; так началась стройка судоверфи, которая вступила в строй в 1940 году.","id":136},{"name":"Николай Григорьевич Галин","role":"Председатель колхоза «Третья пятилетка» в Гырмане","text":"Знаток сельского хозяйства: получал высокие урожаи овощей и картофеля и завёз из Хабаровска саженцы малины, смородины, груши и сливы.","id":155}],"glossary":[["Округ и область","Административные единицы. Нижнеамурский округ создали в 1926 году, а Нижнеамурскую область — в 1934-м, с центром в Николаевске."],["Ликбез","Ликвидация безграмотности: школы и кружки, где взрослых и детей учили читать и писать."],["Изба-читальня","Сельская библиотека и центр просвещения: газеты, книги, лекции, вечера для жителей села."],["Гидроаэропорт","Аэродром для самолётов-гидропланов: летом они садятся на воду, зимой — на лёд."],["ТРАМ","Театр рабочей молодёжи: театр из молодых рабочих-любителей, спектакли которого были связаны с повседневной жизнью."],["Комсомол","ВЛКСМ — Всесоюзный ленинский коммунистический союз молодёжи; ячейки создавали в сёлах и на предприятиях."],["Заездок","Рыболовное сооружение из свай и сетей, которое перегораживает протоку, чтобы вылавливать рыбу."],["Драга","Плавучая машина для добычи золота из речных россыпей."],["Рыбтрест","Государственное объединение рыбных заводов, промыслов и комбинатов на территории округа или области."],["Крайний Север","Районы с особыми льготами и повышенными ценами; в 1940 году Николаевск включили в такой список."]],"quiz":[{"q":"В каком году создали Нижнеамурскую область с центром в Николаевске?","options":["1922","1926","1934","1940"],"a":2,"why":"В 1934 году постановлением ВЦИК; в области было шесть районов, а после 1943 года — семь.","id":106},{"q":"Как называлась первая ежедневная газета, появившаяся в 1924 году (позже «Красный маяк»)?","options":["«Красный Усть-Амурец»","«Стахановец Амура»","«Амурская правда»","«Ленинское знамя»"],"a":0,"why":"«Красный Усть-Амурец»; в 1925 году её переименовали в «Красный маяк», а в 1962-м — в «Ленинское знамя».","id":24},{"q":"Какой самолёт в 1929 году привёз в Николаевск первую авиапочту?","options":["Ш-2","АНТ-4 «Страна Советов»","Ли-2","Ан-2"],"a":1,"why":"Моноплан АНТ-4 «Страна Советов», летевший Москва — Дальний Восток — Нью-Йорк. Встречать его пришло почти всё население.","id":69},{"q":"Сколько самолётов Ш-2 было в первом авиазвене (1934 год)?","options":["1","3","10","30"],"a":1,"why":"Три самолёта Ш-2, каждый мог взять всего до 200 килограммов груза.","id":105},{"q":"Кто совершил первый транспортный рейс на линии Хабаровск — Оха в 1930 году?","options":["Чкалов","Водопьянов","Громов","Гризодубова"],"a":1,"why":"Полярный лётчик, Герой Советского Союза М. В. Водопьянов.","id":74},{"q":"Куда в 1928 году решили вывозить горбушу на экспорт?","options":["В Гамбург","В Лондон","В Нью-Йорк","В Йокогаму"],"a":0,"why":"В Гамбург: об этом принято постановление Президиума Николаевского-на-Амуре исполкома.","id":66},{"q":"Что в 1939 году образовали, когда порт стал морским?","options":["Речное училище","Морское пароходство","Рыбный институт","Аэрофлот"],"a":1,"why":"Николаевское-на-Амуре морское пароходство; ему передали 9 судов от речников и 7 — от Дальневосточного морского пароходства.","id":146},{"q":"Как называлось первое судно, заложенное на судоверфи в 1940 году?","options":["Катер «Димитров»","Сейнер «Умелец»","Теплоход «Метеор»","Пароход «Ола»"],"a":0,"why":"Катер «Димитров» с деревянным корпусом и двигателем в 75 л. с.","id":172}],"tasks":["Сравните записи о медицине 1922, 1930 и 1939 годов. Почему их нельзя сравнивать напрямую (город, район или область)? Как уточнить, о какой территории идёт речь?","Найдите на карте улицу Кантера. Что вам известно о том, в честь кого она названа? Где можно проверить?","Составьте ленту «Связь с миром, 1922–1940»: телефон, радио, газета, авиапочта, воздушные линии, гидроаэропорт. Как менялись расстояния?","Найдите записи о ликбезе, школах и избах-читальнях. Почему в 1920–1930-х годах так много внимания уделяли грамотности?","Хронология этого периода почти целиком рассказывает о строительстве и открытиях. Какие ещё источники (архивы, газеты, воспоминания) нужны, чтобы понять и трудные стороны эпохи? Как ответственно задавать такие вопросы?"],"sources":["Текст записей — хронология автора проекта.","Хронология этого периода пока почти не содержит записей о трудных сторонах эпохи; их предстоит дополнить по документам и воспоминаниям.","Источники по каждой записи уточняются; список проверки — data/vychitka_foundation.csv."]},"perestroika":{"slug":"perestroika","from":1986,"to":1991,"kicker":"Глава 7 · 1986–1991","title":"На пороге перемен","subtitle":"Последние годы хронологии: ТЭЦ, «Мобиль», школы и детские сады, мост к Многовершинному и первое золото","intro":["К середине 1980-х Николаевск был городом с судостроительным заводом, ТЭЦ и растущими микрорайонами. В 1986 году сдали первый панельный дом серии «Мобиль» на улице Сибирской, 130 (90 квартир), открыли бассейн судостроительного завода и школу № 5, которая возникла из слияния двух школ и насчитывала 1 400 учащихся. В посёлке Многовершинный с 1 сентября 1987 года ученики перешли в современное здание школы, построенное по проекту ленинградских архитекторов.","Энергетика росла: ввели четвёртый турбоагрегат ТЭЦ (1987), котёл № 6 (1988), завершили вторую очередь станции, а к 1990 году выработка электроэнергии выросла в 12 раз, тепла — в 13,8 раза. Судостроительный завод строил блок-модули для буровых установок Вьетнама, баржи и танкер; детский сад «Кораблик» на 280 мест избавил заводчан от очереди в дошкольные учреждения. В 1989 году построили мост через реку Лигу — по нему пошли большегрузные автопоезда на Многовершинный, а в 1991 году золотоизвлекательная фабрика дала первое золото.","Город учил и лечил: в 1989–1990 годах в техникуме, медицинском и педагогическом училищах училось рекордное число студентов — 1 174. Строили школы, ПТУ и СПТУ (на 720 мест), открывали музыкальные филиалы в Константиновке и Лазарев. Порт был загружен: на рейде стояли и иностранные суда, а почти каждый день от причала уходил большой теплоход до Хабаровска. В 1991 году, по хронологии, судоремонт и судостроение давали до половины промышленного производства города."],"key":["1986: сдан первый панельный дом серии «Мобиль» (улица Сибирская, 130, 90 квартир); открыты бассейн завода и школа № 5.","1987–1988: ТЭЦ получает четвёртый турбоагрегат и котёл № 6, завершена вторая очередь.","1988: построен и отправлен головной комплект блок-модулей для буровых установок Вьетнама.","1989: мост через реку Лигу открывает путь большегрузным автопоездам на Многовершинный.","1990: основные мощности ТЭЦ построены — выработка электроэнергии выросла в 12 раз, тепла — в 13,8.","1991: золотоизвлекательная фабрика даёт первое золото; строится новое СПТУ на 720 мест."],"timeline":[{"year":1986,"id":636,"title":"Первый «Мобиль» на улице Сибирской"},{"year":1986,"id":637,"title":"Бассейн судостроительного завода"},{"year":1986,"id":638,"title":"Углекислотная станция для сварки"},{"year":1986,"id":639,"title":"Школа № 5 — 1 400 учащихся"},{"year":1986,"id":641,"title":"Новая школа в Многовершинном"},{"year":1986,"id":643,"title":"Красное: микрорайон «Самоцветы» и музей экспедиции"},{"year":1987,"id":644,"title":"Четвёртый турбоагрегат ТЭЦ"},{"year":1987,"id":645,"title":"Плавучий кормозавод для птицесовхоза"},{"year":1987,"id":646,"title":"Спорткомплекс в морском порту"},{"year":1988,"id":647,"title":"Котёл № 6 ТЭЦ"},{"year":1988,"id":649,"title":"Первые блоки из арболита"},{"year":1988,"id":650,"title":"Завершена вторая очередь ТЭЦ"},{"year":1988,"id":651,"title":"Нижнеамурстрой"},{"year":1988,"id":652,"title":"Цеолиты у Иннокентьевки"},{"year":1988,"id":653,"title":"Детский сад «Кораблик»"},{"year":1988,"id":654,"title":"Блок-модули для Вьетнама"},{"year":1988,"id":658,"title":"Итоги десяти лет: баржи, танкер, дамба"},{"year":1988,"id":655,"title":"Красное: ясли, школа, оздоровительный комплекс"},{"year":1989,"id":660,"title":"Школа на 900 мест — на месте сгоревшей"},{"year":1989,"id":662,"title":"24 вида товаров народного потребления"},{"year":1989,"id":664,"title":"Рекордное число студентов"},{"year":1989,"id":668,"title":"Мост через Лигу"},{"year":1989,"id":669,"title":"Маго: комплексное предприятие вместо рейда"},{"year":1989,"id":670,"title":"Чля: детсад и школа в одном здании"},{"year":1989,"id":671,"title":"Озерпах в 1989 году"},{"year":1989,"id":672,"title":"Новый рыбозавод в Пуире"},{"year":1989,"id":673,"title":"Красное: котельная и ЛЭП"},{"year":1990,"id":674,"title":"ТЭЦ: мощности достроены"},{"year":1990,"id":675,"title":"Новые специальности техникума"},{"year":1990,"id":676,"title":"Кинопредприятие"},{"year":1990,"id":679,"title":"Коррекционный детский дом"},{"year":1990,"id":680,"title":"Программа жилья до 2000 года"},{"year":1990,"id":681,"title":"Планы: ПТУ, Дворец культуры и колхоз имени Блюхера"},{"year":1990,"id":682,"title":"Музыкальная школа в Константиновке"},{"year":1991,"id":688,"title":"ПТУ: новые специальности"},{"year":1991,"id":689,"title":"Начальная школа № 6"},{"year":1991,"id":690,"title":"Судостроение и судоремонт — до половины промышленности"},{"year":1991,"id":691,"title":"Музыкальная школа в Лазареве"},{"year":1991,"id":692,"title":"Новое СПТУ на 720 мест"},{"year":1991,"id":693,"title":"Первое золото"},{"year":1991,"id":696,"title":"Первый в крае детсад для детей-инвалидов"},{"year":1991,"id":697,"title":"Пять школ искусств и два филиала"},{"year":1991,"id":698,"title":"Порт и теплоход до Хабаровска"}],"compare":[{"title":"Рост выработки на ТЭЦ после реконструкции","note":"Во сколько раз выросла выработка, 1990 год","a":{"label":"Электричество","value":12},"b":{"label":"Тепло","value":13.8},"result":"Электроэнергии станция вырабатывала в 12 раз больше, тепла — в 13,8 раза; мощность — 130,6 МВт по электроэнергии и 321 Гкал/час по теплу.","id":674}],"stack":{"title":"Что построил судостроительный завод за десять лет (к 1989 году)","note":"Построено единиц","unit":" шт.","parts":[{"label":"Баржи-площадки проекта 942 (тысячетонные)","value":11},{"label":"Бункерные баржи","value":3},{"label":"Самоходный танкер проекта Р-135","value":1}],"id":658},"mapLinks":[{"title":"Первый «Мобиль» на Сибирской, 130 (1986)","text":"В 1986 году на улице Сибирской, 130 приняли в эксплуатацию первый панельный 90-квартирный дом серии «Мобиль».","streets":["Сибирская улица"]},{"title":"Красное: «Самоцветы», музей экспедиции","text":"В микрорайоне «Самоцветы» появились контора экспедиции, цех по изделиям из камнесамоцветного сырья, общежитие, столовая, бассейн с сауной; на первом этаже конторы — музей экспедиции с образцами лунного камня.","places":["Красное"]},{"title":"Чля: детсад, школа и мост к Многовершинному","text":"В Чле построили двухэтажное кирпичное здание для детского сада и школы; в начале 1990-х здесь жили более 1 800 человек. Рядом — трасса на Многовершинный с мостом через Лигу.","places":["Чля"]}],"people":[{"name":"Василий Николаевич Бычковский","role":"Инициатор и организатор углекислотной станции завода","text":"В 1986 году станция мощностью 2,4 тонны углекислоты в сутки избавила завод от постоянной погрузки и разгрузки баллонов, которые везли из Хабаровска и Комсомольска.","id":638},{"name":"Л. С. Цой","role":"Директор школы в посёлке Многовершинный","text":"С 1 сентября 1987 года школа перешла в современное здание, построенное по проекту ленинградских архитекторов.","id":641}],"glossary":[["Арболит","Лёгкий строительный материал из цемента и древесной щепы; из него делают блоки для стен."],["Цеолиты","Природные минералы с мельчайшими порами: их используют для очистки воды и газов, в сельском хозяйстве и других отраслях."],["Углекислота","Углекислый газ в баллонах; на судостроительных заводах применяется при сварке."],["ТНП","Товары народного потребления: вещи для дома и быта, в том числе дачные домики, столы, шкафы, спальные мешки."],["Знак качества","Государственный знак качества СССР — отметка лучшей продукции."],["СПТУ","Среднее профессионально-техническое училище: давало и профессию, и среднее образование."],["Энергоблок","Котёл и турбина, которые вместе вырабатывают электричество на станции."],["Золотоизвлекательная фабрика","Предприятие, где из добытой руды извлекают золото."]],"quiz":[{"q":"На какой улице построили первый панельный дом серии «Мобиль» (1986 год)?","options":["Советской","Сибирской","Школьной","Гоголя"],"a":1,"why":"На улице Сибирской, 130: 90-квартирный дом.","id":636},{"q":"Сколько квартир в этом первом доме серии «Мобиль»?","options":["9","45","90","290"],"a":2,"why":"90 квартир.","id":636},{"q":"Для какого предприятия в 1987 году построили плавучий кормозавод по выработке витаминной муки?","options":["Для рыбозавода","Для птицесовхоза","Для колхоза","Для порта"],"a":1,"why":"Для Николаевского птицесовхоза. Таких кормозаводов было два в СССР: один на Оби и один на Дальнем Востоке.","id":645},{"q":"На сколько мест построили детский сад «Кораблик» с бассейном и зимним садом?","options":["28","80","280","1 280"],"a":2,"why":"На 280 мест: после его ввода на заводе ликвидировали очередь в детские сады.","id":653},{"q":"Для какой страны построили головной комплект блок-модулей верхних строений буровых установок в 1988 году?","options":["Индонезия","Куба","Вьетнам","Египет"],"a":2,"why":"Для Демократической Республики Вьетнам.","id":654},{"q":"Через какую реку в 1989 году построили мост на трассе Николаевск — Многовершинный?","options":["Амгунь","Лигу","Тугур","Патху"],"a":1,"why":"Через реку Лигу: мост длиной 65 метров, по нему пошли большегрузные автопоезда.","id":668},{"q":"Во сколько раз выросла выработка электроэнергии на ТЭЦ после реконструкции и модернизации к 1990 году?","options":["В 2 раза","В 5 раз","В 12 раз","В 50 раз"],"a":2,"why":"В 12 раз (тепла — в 13,8 раза).","id":674},{"q":"Что в 1991 году дала золотоизвлекательная фабрика?","options":["Первое золото","Первый уголь","Первую нефть","Первую медь"],"a":0,"why":"Первое золото — Многовершинное месторождение осваивали с 1980 года.","id":693}],"tasks":["Найдите на карте улицу Сибирскую. Сколько таких домов, как первый «Мобиль» (90 квартир), нужно построить, чтобы дать жильё 1 000 семьям?","Сравните две цифры: «Мобиль» (1984) мог давать до 50 тыс. кв. м жилья в год, а завод в 1990 году строил около 100 квартир в год. Почему цифры так различаются? О каких предприятиях речь?","Составьте список учебных заведений, открытых или строящихся в 1986–1991 годах (школы, СПТУ, техникум, музыкальные филиалы). Что это говорит о жизни города?","Прочитайте запись про Озерпах (1989). Какие числа вы находите? Что известно из записи, а что нужно выяснить у других источников?","Запись 1991 года про порт упоминает марш «Прощание славянки» и ежедневный теплоход до Хабаровска. Чем такое свидетельство отличается от таблицы с цифрами? Что оно добавляет к картине города?"],"sources":["Текст записей — хронология автора проекта.","Часть записей 1990 года (проект школы в Красном) содержит авторские оценки событий; в главу они не вынесены.","Источники по каждой записи уточняются; список проверки — data/vychitka_perestroika.csv."]}};